import { NextResponse } from "next/server";
import { writeFile, mkdir } from "fs/promises";
import { join } from "path";
import { requireAuth } from "@/lib/require-auth";
import os from "os";

export async function POST(request: Request) {
  const auth = requireAuth(request);
  if (auth.error) return auth.error;

  try {
    const formData = await request.formData();
    const file = formData.get("file") as File;

    if (!file) {
      return NextResponse.json({ error: "No file provided" }, { status: 400 });
    }

    if (file.type !== "application/pdf") {
      return NextResponse.json(
        { error: "Only PDF files are allowed" },
        { status: 400 },
      );
    }

    if (file.size > 10 * 1024 * 1024) {
      return NextResponse.json(
        { error: "File size must be less than 10MB" },
        { status: 400 },
      );
    }

    const bytes = await file.arrayBuffer();
    const buffer = Buffer.from(bytes);

    const timestamp = Date.now();
    const originalName = file.name.replace(/\s+/g, "-").toLowerCase();
    const filename = `${timestamp}-${originalName}`;

    const candidates = [
      join(process.cwd(), "..", "website", "assets", "expense-bills"),
      join(process.cwd(), "website", "assets", "expense-bills"),
      join(process.cwd(), "public", "uploads", "expense-bills"),
      join(os.tmpdir(), "pixelatenest", "expense-bills"),
    ];

    let uploadDir: string | null = null;
    for (const cand of candidates) {
      try {
        await mkdir(cand, { recursive: true });
        uploadDir = cand;
        break;
      } catch {
        // try next candidate
      }
    }

    if (!uploadDir) {
      return NextResponse.json(
        { error: "Could not create upload directory" },
        { status: 500 },
      );
    }

    const filePath = join(uploadDir, filename);
    await writeFile(filePath, buffer);

    let url: string;
    if (uploadDir.includes("public")) {
      url = `/uploads/expense-bills/${filename}`;
    } else if (uploadDir.includes(os.tmpdir())) {
      url = `file://${filePath}`;
    } else {
      url = `/assets/expense-bills/${filename}`;
    }

    return NextResponse.json({ success: true, url, filename });
  } catch (error: any) {
    console.error("Expense bill upload error:", error);
    return NextResponse.json(
      { error: error.message || "Failed to upload file" },
      { status: 500 },
    );
  }
}
